(()=>{
  'use strict';
  const lang=()=>document.documentElement.lang?.toLowerCase().startsWith('en')?'en':'pl';
  const messages={
    claim:{ok:{pl:'Tak. Na tym etapie można opisać tylko to, co rzeczywiście widać. Narodowość mężczyzny i miejsce nagrania są twierdzeniami z opisu posta, a nie informacjami potwierdzonymi przez sam film.',en:'Yes. At this stage you can describe only what is actually visible. The man’s nationality and the location are claims from the post caption, not facts confirmed by the video itself.'},bad:{pl:'Jeszcze nie. Oddziel to, co widać na filmie, od tego, co dopisał autor posta. Sam materiał nie potwierdza ani narodowości mężczyzny, ani miejsca nagrania.',en:'Not yet. Separate what is visible in the video from what the post author added. The material itself confirms neither the man’s nationality nor the filming location.'}},
    evidence:{ok:{pl:'Tak. Piwo, piosenka i model autobusu są użytecznymi tropami, ale najsilniejszy dowód stanowi geolokalizacja oparta na zgodnych elementach otoczenia i dodatkowym potwierdzeniu miejsca.',en:'Yes. The beer, song and bus model are useful clues, but the strongest evidence is the geolocation based on matching environmental details plus additional confirmation of the location.'},bad:{pl:'Niezupełnie. Ten element może być poszlaką, ale sam nie rozstrzyga miejsca nagrania. Szukaj dowodu, który łączy kilka zgodnych cech z konkretną lokalizacją.',en:'Not quite. This element can be a clue, but it does not determine the filming location on its own. Look for evidence that links several matching features to a specific place.'}},
    context:{ok:{pl:'Tak. Problemem nie jest autentyczność samego nagrania, lecz przypisany mu opis. To przykład fałszywego kontekstu.',en:'Yes. The problem is not the authenticity of the footage itself but the caption attached to it. This is an example of false context.'},bad:{pl:'Jeszcze nie. Weryfikacja nie wykazała, że film jest syntetyczny. Ustalenia dotyczą przede wszystkim błędnego kontekstu przypisanego autentycznemu nagraniu.',en:'Not yet. The verification did not show that the video was synthetic. The findings concern the false context attached to authentic footage.'}}
  };
  function clear(field){field?.querySelectorAll('.v167-answer-correct,.v167-answer-incorrect').forEach(label=>{label.classList.remove('v167-answer-correct','v167-answer-incorrect');label.querySelector('.v167-answer-state-badge')?.remove();});}
  function mark(field,input,ok){clear(field);const label=input?.closest('label');if(!label)return;label.classList.add(ok?'v167-answer-correct':'v167-answer-incorrect');const span=[...label.children].find(el=>el.tagName==='SPAN');if(span){span.classList.add('v168-answer-content');const badge=document.createElement('span');badge.className='v167-answer-state-badge';badge.textContent=lang()==='en'?(ok?'✓ Correct answer':'✕ Incorrect answer'):(ok?'✓ Poprawna odpowiedź':'✕ Błędna odpowiedź');span.append(badge);}}
  function check(key){const field=document.querySelector(`[data-v170-question="${key}"]`);const chosen=field?.querySelector('input:checked');const fb=document.querySelector(`[data-v170-feedback="${key}"]`);if(!chosen){if(fb){fb.className='v170-feedback is-wrong';fb.textContent=lang()==='en'?'Choose one answer first.':'Najpierw wybierz jedną odpowiedź.';}return false;}const ok=chosen.value===field.dataset.correct;mark(field,chosen,ok);if(fb){fb.className='v170-feedback '+(ok?'is-correct':'is-wrong');fb.textContent=messages[key][ok?'ok':'bad'][lang()];}return ok;}
  document.querySelector('[data-v170-check="claim"]')?.addEventListener('click',()=>{const field=document.querySelector('[data-v170-question="claim"]');if(!field?.querySelector('input:checked')){check('claim');return;}check('claim');const evidence=document.querySelector('[data-v170-evidence]');if(evidence){evidence.hidden=false;evidence.scrollIntoView({behavior:'smooth',block:'nearest'});}});
  document.querySelector('[data-v170-check="final"]')?.addEventListener('click',()=>{const e=document.querySelector('[data-v170-question="evidence"]')?.querySelector('input:checked');const c=document.querySelector('[data-v170-question="context"]')?.querySelector('input:checked');if(!e||!c){if(e)check('evidence');if(c)check('context');const missing=!e?'evidence':'context';const fb=document.querySelector(`[data-v170-feedback="${missing}"]`);if(fb&&!fb.textContent){fb.className='v170-feedback is-wrong';fb.textContent=lang()==='en'?'Choose one answer first.':'Najpierw wybierz jedną odpowiedź.';}return;}const ok1=check('evidence'),ok2=check('context');const conclusion=document.querySelector('[data-v170-conclusion]');if(conclusion){conclusion.hidden=false;if(ok1&&ok2)conclusion.scrollIntoView({behavior:'smooth',block:'nearest'});}});
  document.querySelectorAll('[data-v170-question] input').forEach(input=>input.addEventListener('change',()=>{const field=input.closest('[data-v170-question]');clear(field);const fb=field?.querySelector('.v170-feedback');if(fb){fb.className='v170-feedback';fb.textContent='';}}));
})();
